module github.com/acme/orderd

go 1.22

require (
	github.com/google/uuid/v2 v2.0.1
	github.com/redis/go-redis/v9 v9.5.1
	golang.org/x/sync v0.7.0
)

require (
	github.com/cespare/xxhash/v2 v2.2.0 // indirect
	github.com/dgryski/go-rendezvous v0.0.0-20200823014737-9f7001d12a5f // indirect
)

// 紧急打热补丁: 用我们自己 fork 的版本绕过上游 v9.5.1 的连接泄漏
replace github.com/redis/go-redis/v9 => github.com/acme/go-redis/v9 v9.5.1-acmefix.2

// 本地联调时用相对路径; 发版前必须删掉,否则下游拉不到
// replace github.com/acme/payments => ../payments

// 这两个版本有已知数据竞争, 让 MVS 跳过它们
exclude (
	github.com/redis/go-redis/v9 v9.4.0
	github.com/redis/go-redis/v9 v9.4.1
)

// 我们自己发的 v1.3.0 有 bug, 标记作废, 下游 go get 会收到 'retracted' 警告
retract (
	v1.3.0
	[v1.2.0, v1.2.5] // 整个区间都作废
)
